// Escucha un peso de UNA bola (topic .../peso/<n>) y publica el estado COMPLETO
// de las bolas a NATS. El dashboard espera el arreglo entero de valvuladoras,
// así que guardamos el último peso de cada bola en flow.pesos y lo mandamos
// todo junto cada vez que llega un peso nuevo.
//
// AJUSTA por silo:
const MACHINE_CODE = 'B2-A-silo-1';
const NUM_BOLAS    = 3;          // silo 1/4 = 3 bolas, silo 2/3 = 2
const PESO_PRODUCTO = 20;        // tope de llenado (kg). Solo informativo aquí.

// --- Sacar el índice de bola del topic: envasadora/.../peso/1 -> 0 ---
const partes = String(msg.topic || '').split('/');
const nBola = parseInt(partes[partes.length - 1], 10); // 1,2,3
if (isNaN(nBola) || nBola < 1 || nBola > NUM_BOLAS) {
    node.warn('Topic de peso no reconocido: ' + msg.topic);
    return null;
}
const idx = nBola - 1;

// --- El peso puede venir como número o como texto ('7.4') ---
let peso = (typeof msg.payload === 'number') ? msg.payload : parseFloat(msg.payload);
if (isNaN(peso) || peso < 0) peso = 0;

// --- Guardar el último peso de cada bola ---
let pesos = flow.get('pesos');
if (!Array.isArray(pesos) || pesos.length !== NUM_BOLAS) {
    pesos = new Array(NUM_BOLAS).fill(0);
}
pesos[idx] = Math.round(peso * 10) / 10;
flow.set('pesos', pesos);

// --- Armar el estado completo que espera el dashboard ---
// Solo mandamos el peso; el resto (setpoint, columna, leds, bultos) va en
// cero/false porque por ahora el PLC solo publica el peso.
const valvuladoras = pesos.map(function (p) {
    return {
        peso: p,
        setpoint: 0,
        columna: 0,
        leds: { paro: false, limpieza: false, ciclo: false },
        bultos: 0
    };
});

msg.topic = 'papid.envasadora.' + MACHINE_CODE;
msg.payload = {
    machine_code: MACHINE_CODE,
    peso_producto: PESO_PRODUCTO,
    valvuladoras: valvuladoras
};
node.status({ fill: 'green', shape: 'dot', text: 'bola ' + nBola + ' = ' + pesos[idx] + ' kg' });
return msg;
